mapper.select:
SELECT AREAKY AS "VALUE_COL"
   ,   SHORTX AS "TEXT_COL"
FROM   AREMA
WHERE  COMPKY = #{SES_USER_COMPANY}
AND    WAREKY = #{SES_WAREKY}

	SELECT AREAKY AS "AREAKY"
	   ,   ZONEKY AS "ZONEKY"
	   ,   SHORTX AS "ZONENM"
	FROM   ZONMA
	WHERE  COMPKY = #{SES_USER_COMPANY}
    AND    WAREKY = #{SES_WAREKY}

SELECT A.AREAKY AS "AREAKY" , C.SHORTX AS "AREANM" , A.ZONEKY AS "ZONEKY" , B.SHORTX AS "ZONENM" , A.LOCAKY AS "LOCAKY" , A.SHORTX AS "LOCANM" FROM LOCMA A INNER JOIN ZONMA B ON A.COMPKY = B.COMPKY AND A.WAREKY = B.WAREKY AND A.ZONEKY = B.ZONEKY AND A.AREAKY = B.AREAKY INNER JOIN AREMA C ON B.COMPKY = C.COMPKY AND B.WAREKY = C.WAREKY AND B.AREAKY = C.AREAKY WHERE A.COMPKY = #{SES_USER_COMPANY} AND A.WAREKY = #{SES_WAREKY}
AND A.ZONEKY LIKE '%'|| #{ZONEKY} ||'%'
AND A.LOCAKY = #{LOCAKY}
ORDER BY A.COMPKY, A.WAREKY, A.AREAKY

SELECT A.COL1 AS "COL1" , A.COL2 AS "COL2" , A.COL3 AS "COL3" FROM( SELECT '1' AS COL1, 'COLUMN_DATA1' AS COL2, 'TYPE1' AS COL3 UNION ALL SELECT '2' AS COL1, 'COLUMN_DATA2' AS COL2, 'TYPE1' AS COL3 UNION ALL SELECT '3' AS COL1, 'COLUMN_DATA3' AS COL2, 'TYPE1' AS COL3 UNION ALL SELECT '4' AS COL1, 'COLUMN_DATA4' AS COL2, 'TYPE2' AS COL3 UNION ALL SELECT '5' AS COL1, 'COLUMN_DATA5' AS COL2, 'TYPE2' AS COL3 UNION ALL SELECT '6' AS COL1, 'COLUMN_DATA6' AS COL2, 'TYPE2' AS COL3 UNION ALL SELECT '7' AS COL1, 'COLUMN_DATA7' AS COL2, 'TYPE3' AS COL3 UNION ALL SELECT '8' AS COL1, 'COLUMN_DATA8' AS COL2, 'TYPE3' AS COL3 ) A WHERE 1=1
AND A.COL3 != #{TYPE}
AND A.COL3 != #{COMBO1}
AND A.COL3 != #{COMBO2}
AND A.COL1 LIKE '%'|| #{COL1} ||'%'
AND A.COL2 LIKE '%'|| #{COL2} ||'%'

SELECT COUNT(1) AS "CNT"
FROM   TASDH
WHERE  COMPKY = #{SES_USER_COMPANY}
AND    TASKKY = #{TASKKY}
AND    STATDO = 'FPC'

SELECT DISTINCT S.SHPOKY AS "SHPOKY" , H.WAREKY AS "WAREKY" , I.TASKTY AS "TASKTY" , S.SHPMTY AS "SHPMTY" , T.SHORTX AS "SHPMNM" , S.RQSHPD AS "RQSHPD" , H.STATDO AS "STATDO" , V.CDESC1 AS "STATNM" , S.DPTNKY AS "PTNRKY" , S.DNAME1 AS "PTNRNM" , S.PTRCVR AS "PTRCVR" , S.DNAME2 AS "PTRCNM" FROM TASDH H INNER JOIN TASDI I ON H.COMPKY = I.COMPKY AND H.TASKKY = I.TASKKY AND I.STATIT != 'CLS' INNER JOIN SHPDH S ON I.COMPKY = S.COMPKY AND I.SHPOKY = S.SHPOKY INNER JOIN DOCTM T ON S.DOCCAT = T.DOCCAT AND S.SHPMTY = T.DOCUTY INNER JOIN CMCDV V ON H.STATDO = V.CMCDVL AND V.CMCDKY = 'STATDO' WHERE H.COMPKY = #{SES_USER_COMPANY} AND S.SHPMTY = '201'
AND S.SHPOKY = #{SHPOKY}
AND I.TASKTY = 'PK' AND S.STATDO NOT IN('FSH', 'PSH') ORDER BY S.SHPOKY ASC

SELECT A.SVBELN AS "SVBELN" , A.RQSHPD AS "RQSHPD" , CASE WHEN A.SHPOKY = '' THEN 'WAVE 생성 전' WHEN A.QTALOC = 0 THEN '미작업' WHEN (A.QTALOC > 0 AND A.QTJCMP = 0 AND A.QTSHPD = 0) THEN '할당완료' WHEN (A.QTALOC > 0 AND A.QTJCMP > 0 AND A.QTSHPD = 0) THEN '피킹완료' WHEN (A.QTALOC > 0 AND A.QTJCMP > 0 AND A.QTSHPD > 0) THEN '출고완료' END AS "STATDO" , A.PTNRKY AS "PTNRKY" , A.PTNRNM AS "PTNRNM" , A.PTRCVR AS "PTRCVR" , A.PTRCNM AS "PTRCNM" , A.SHPOKY AS "SHPOKY" FROM( SELECT A.SVBELN , A.RQSHPD , A.PTNRKY , A.PTNRNM , A.PTRCVR , A.PTRCNM , SUM(A.QTYORD :: INT) AS QTYORD , SUM(COALESCE(B.QTALOC :: INT, 0)) AS QTALOC , SUM(COALESCE(B.QTJCMP :: INT, 0)) AS QTJCMP , SUM(COALESCE(B.QTSHPD :: INT, 0)) AS QTSHPD , COALESCE(B.SHPOKY,'') AS SHPOKY FROM IFSHP A LEFT OUTER JOIN SHPDI B ON A.COMPKY = B.COMPKY AND A.SVBELN = B.SVBELN AND A.SPOSNR = B.SPOSNR WHERE A.COMPKY = #{SES_USER_COMPANY}
AND A.SVBELN = #{SVBELN}
AND A.RQSHPD = #{RQSHPD}
GROUP BY A.SVBELN , A.RQSHPD , A.PTNRKY , A.PTNRNM , A.PTRCVR , A.PTRCNM , B.SHPOKY ) A WHERE 1=1
AND A.SHPOKY = ''
AND A.QTALOC = 0
AND (A.QTALOC > 0 AND A.QTJCMP = 0 AND A.QTSHPD = 0)
AND (A.QTALOC > 0 AND A.QTJCMP > 0 AND A.QTSHPD = 0)
AND (A.QTALOC > 0 AND A.QTJCMP > 0 AND A.QTSHPD > 0)
ORDER BY A.SVBELN DESC
